INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13245, 'koKR', 'Dowód zgonu: Ingvar Łupieżca', 'Zbierz drużynę i poprowadź ją do Twierdzy Utgard. Masz tam odnaleźć i zabić Ingvara Łupieżcę, zanim poprowadzi swoje wrykulskie siły, by złupić pobliskie osady Przymierza i Hordy.$B$BPotrzebuję jego topora jako dowodu, że się z nim rozprawiono. Nie chodzi o to, że ci nie ufam. Po prostu roztropnie jest mieć pewność, że rzecz została zrobiona.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Toporem Łupieżcy.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13245, 'koKR', 'Bardzo dobrze. Połóż topór tam, pod ścianą.$b$bJestem pewien, że w Valgardzie i Przystani Zemsty będą dziś spać spokojniej, wiedząc, że $gporadziłeś:poradziłaś; sobie z tym dzikusem.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13245, 'koKR', 'Masz topór? Ingvar nie żyje?', 0);
